async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  message: ListSessionsMessage,
  sessionStore?: SessionStore
): Promise<void> {
  try {
    const summaries = sessionStore?.listFor
      ? await sessionStore.listFor(session.userId, {limit: message.limit, before: message.before})
      : [];
    sendSessionList(ws, summaries.map(toSummaryFrame));
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    log.error('ws', 'session list failed', {userId: session.userId, error: reason});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list sessions');
  }
}

function toSummaryFrame(summary: SessionSummary): SessionSummaryFrame {
  return {
    sessionId: summary.sessionId,
    createdAt: summary.createdAt.toISOString(),
    updatedAt: summary.updatedAt.toISOString(),
    entryCount: summary.entryCount,
  };
}

